              "autosize": true,
              "blocks": [{
                "key": "8h8sr",
                "text": "Za sam kraj večere stigao je slijed u sharing konceptu, formatu koji je trenutačno iznimno popularan u suvremenoj gastronomiji. Na nekoliko pladnjeva poslužen je hrskavi pomfrit, sočno narezan steak i prozračna cacio e pepe pjena koje su parovi međusobno dijelili, kušali i komentirali. Cijelu je priču zaokružio koktel Balkan Colada: zavodljiva kombinacija ruma, orahovca i Malibua.",
                "entityRanges": [],
                "depth": 0
              }],
